using OpenAI.Chat;
using System.Runtime.CompilerServices;

public static class StreamingChatEndpoints
{
    public static void MapAiStreamingEndpoints(this IEndpointRouteBuilder app)
    {
        app.MapPost("/api/ai/stream", async (
            ChatRequest request,
            ChatClient chatClient,
            HttpContext httpContext,
            CancellationToken ct) =>
        {
            httpContext.Response.ContentType = "text/event-stream";
            httpContext.Response.Headers.Append("Cache-Control", "no-cache");
            httpContext.Response.Headers.Append("Connection", "keep-alive");

            var messages = new ChatMessage[]
            {
                new SystemChatMessage("You are a helpful assistant."),
                new UserChatMessage(request.Prompt)
            };

            try
            {
                AsyncCollectionResult<StreamingChatCompletionUpdate> stream =
                    chatClient.CompleteChatStreamingAsync(messages, cancellationToken: ct);

                await foreach (StreamingChatCompletionUpdate update in stream)
                {
                    ct.ThrowIfCancellationRequested();

                    foreach (ChatMessageContentPart part in update.ContentUpdate)
                    {
                        if (!string.IsNullOrEmpty(part.Text))
                        {
                            // Write SSE format: 'data: {text}\n\n'
                            await httpContext.Response.WriteAsync($"data: {part.Text}\n\n", ct);
                            await httpContext.Response.Body.FlushAsync(ct);
                        }
                    }
                }

                await httpContext.Response.WriteAsync("data: [DONE]\n\n", ct);
            }
            catch (OperationCanceledException)
            {
                // Client cancelled or closed tab - exit cleanly
            }
            catch (Exception ex)
            {
                // Mid-stream error event notification
                await httpContext.Response.WriteAsync($"event: error\ndata: {ex.Message}\n\n", CancellationToken.None);
            }
        });
    }
}

public record ChatRequest(string Prompt);
